import type { AgeGroup, Question, QuizSubject } from "../types";

interface QSeed {
  q: string;
  opts: string[];
  a: number; // answerIndex
  exp: string;
}

let counter = 0;
function build(ageGroup: AgeGroup, subject: QuizSubject, items: QSeed[]): Question[] {
  return items.map((it) => {
    counter += 1;
    return {
      id: `q-core-${counter}`,
      ageGroup,
      subject,
      question: it.q,
      options: it.opts,
      answerIndex: it.a,
      explanation: it.exp,
      active: true,
    };
  });
}

